программ, приложении и конечно же веб-сайтов (FrontEnd). \n                            За эти прошедшие два года я начал понимать базовую архитектуру вёрстки сайта, работать с их компонентами, \n                                грамотно применять к сайтам дизайн и в целом научился создавать веб-сайты. \n                                    На самом деле, 1 простой веб-сайт можно создать за 1-4 часа. \n                                        В современном программировании мне нравится делать веб-сайты! \n                                            Кстати с 2021 по 2022 гг. я ходил на курсы программирования Python в «Бизнес Центр», \n                                                а также я верстал тест с мини-вопросами, в этом же месте на этом же языке программирования - Python. \n                                                    К сожалению я не смогу продемонстрировать эти результаты, \n                                                        ведь на данный момент они не сохранились у меня в галерее или на диске каком нибудь.\n        ",o(`${i}/mines/blocks/block/blockdev/textdevP/panda/panda.CSS`);var Po=`${i}/mines/blocks/block/blockdev/textdevP/panda/CITPanda.PNG`;const Eo=document.createElement("img");Eo.id="CITPanda",Eo.src=Po;const Ho=document.createElement("p");Ho.className="citdev",Ho.innerHTML=`\n            ${f.textContent}реподаватели в моём ИТ-Колледже — практики из IT-Сферы FrontEnd'a, которые знают, что действительно важно в профессии. \n                ${f.textContent}люс в колледже есть современные сайты со своими программами, где например можно тестировать и показывать свои проекты. \n                    ${f.textContent}осле первого курса я хотел углубиться во FrontEnd-разработку, а теперь после второго настало время для применения своих практических знаний уже на стажировках. \n                        Впереди ещё не так уж и много интересного: участие в глобальных проектах, испытания и конечно же дипломный проект! \n                            Если ты по прежнему интересуешься Будущими Информационными Технологиями — этот колледж отличный старт для карьеры в цифровом мире.\n                        ${P.outerHTML}\n                            Где находится колледж?\n                            ${P.outerHTML}\n                                Колледж расположен на Юго-Западном районе Екатеринбурга, адрес: улица Чкалова, 3.\n                                ${P.outerHTML}\n                                    ${f.textContent}осмотреть на карте:\n        `.trim();const ko=document.createElement("a");ko.className="textdevp",ko.innerHTML=`\n            ${On.outerHTML}\n                ${So.outerHTML}\n                    ${$o.outerHTML}\n                        ${Eo.outerHTML}\n                            ${Ho.outerHTML}\n        `,setTimeout(()=>{document.querySelectorAll("#profile a").forEach(t=>{t.removeEventListener("mouseenter",Co),t.addEventListener("mouseenter",function(e){console.log("Mouse entered:",t),Co(e),t.classList.add("activate")}),t.addEventListener("click",wo)}),Co(1)},0);var zo,No={exports:{}};/* @preserve * Leaflet 1.9.4, a JS library for interactive maps. https://leafletjs.com * (c) 2010-2023 Vladimir Agafonkin, (c) 2010-2011 CloudMade */var Zo=(zo||(zo=1,function(t,e){!function(t){var e="1.9.4";function n(t){var e,n,o,i;for(n=1,o=arguments.length;n<o;n++)for(e in i=arguments[n])t[e]=i[e];return t}var o=Object.create||function(){function t(){}return function(e){return t.prototype=e,new t}}();function i(t,e){var n=Array.prototype.slice;if(t.bind)return t.bind.apply(t,n.call(arguments,1));var o=n.call(arguments,2);return function(){return t.apply(e,o.length?o.concat(n.call(arguments)):arguments)}}var s=0;function r(t){return"_leaflet_id"in t||(t._leaflet_id=++s),t._leaflet_id}function a(t,e,n){var o,i,s,r;return r=function(){o=!1,i&&(s.apply(n,i),i=!1)},s=function(){o?i=arguments:(t.apply(n,arguments),setTimeout(r,e),o=!0)},s}function c(t,e,n){var o=e[1],i=e[0],s=o-i;return t===o&&n?t:((t-i)%s+s)%s+i}f